function validate_cnic_details(frm) {
    const {
        custom_cnic_no,
        custom_cnic_issue_date,
        custom_cnic_expiry_date
    } = frm.doc;

    if (custom_cnic_no) {
        const cnicRegex = /^\d{13}$/;

        if (!cnicRegex.test(custom_cnic_no)) {
            frappe.throw(__('CNIC must be exactly 13 digits without dashes.'));
        }

        if (custom_cnic_no === "0000000000000") {
            frappe.throw(__('Invalid CNIC number.'));
        }
    }

    if (custom_cnic_issue_date) {
        const today = frappe.datetime.get_today();

        if (custom_cnic_issue_date > today) {
            frappe.throw(__('CNIC Issue Date cannot be in the future.'));
        }
    }

    if (custom_cnic_expiry_date) {
        const today = frappe.datetime.get_today();

        if (custom_cnic_expiry_date < today) {
            frappe.throw(__('CNIC Expiry Date cannot be in the past.'));
        }
    }

    if (custom_cnic_issue_date && custom_cnic_expiry_date) {
        if (custom_cnic_expiry_date <= custom_cnic_issue_date) {
            frappe.throw(__('CNIC Expiry Date must be after Issue Date.'));
        }
    }
}

frappe.ui.form.on('Customer', {
    refresh(frm) {
        // your code here
    },
    validate: (frm) => {
        validate_cnic_details(frm);
    },
    custom_cnic_no: (frm) => {
        validate_cnic_details(frm);
    },
    custom_cnic_expiry_date: (frm) => {
        validate_cnic_details(frm);
    },
    custom_cnic_issue_date: (frm) => {
        validate_cnic_details(frm);
    },
})
